python3 -c "
import pathlib
p = pathlib.Path('crates/elephc-magician/src/interpreter/builtins/filesystem/glob.rs')
t = p.read_text()
bad = '\"Warning: glob(): At least one of the passed flags is invalid or not supported              on this platform\\\\n\",'
good = '''\"Warning: glob(): At least one of the passed flags is invalid or not supported \"
            \"on this platform\\\\n\",'''
assert t.count(bad) == 1, 'message not found: %d' % t.count(bad)
t = t.replace(bad, good, 1)
old = '''pub(in crate::interpreter) fn eval_glob_matches(pattern: &str) -> Vec<String> {
    eval_glob_matches_one(pattern, 0)
}'''
new = '''pub(in crate::interpreter) fn eval_glob_matches(pattern: &str) -> Vec<String> {
    let mut matches = eval_glob_matches_one(pattern, 0);
    // The flag-aware caller sorts each brace expansion itself; this one has other callers that
    // have always been handed a sorted listing, so the sort stays here for them.
    matches.sort();
    matches
}'''
assert t.count(old) == 1, 'matches wrapper not found'
t = t.replace(old, new, 1)
p.write_text(t)
print('message and sort fixed')
": message and sort fixed
